            Object dueDate = inv.get("dueDate");
            // Amount is derived from the invoice's line items (V13), so it is not seeded directly;
            // the column defaults to 0.
            jdbc.update(
                    "INSERT INTO invoices (id, project_id, status, issued_date, due_date)"
                            + " VALUES (?, ?, ?, ?, ?)",
